import os,json,subprocess,concurrent.futures,re
from pathlib import Path
files=[]
for root in ['/Volumes/A3','/Volumes/A4','/Volumes/MicroSD']:
 for p,ds,fs in os.walk(root):
  ds[:]=[d for d in ds if not d.startswith('.')]
  for f in fs:
   if f.startswith('.'):continue
   camera=f.lower().endswith(('.mp4','.mov'))
   audio=f.lower().endswith('.wav') and bool(re.search(r'_[12](?:[^0-9]*)\.wav$',f,re.I))
   if camera or audio:files.append((str(Path(p)/f),'camera' if camera else 'microphone'))
def probe(x):
 p,kind=x;s=Path(p).stat()
 r=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_format','-show_streams','-of','json',p]))
 return dict(path=p,kind=kind,bytes=s.st_size,mtimeNs=s.st_mtime_ns,probe=r)
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as e:out=list(e.map(probe,files))
Path('analysis/card-podcasts-2026-10-28/inventory.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
for x in out:
 f=x['probe']['format'];ss=x['probe']['streams'];print(json.dumps({'path':x['path'],'duration':f['duration'],'tags':f.get('tags'), 'streams':[{k:s.get(k) for k in ['codec_type','codec_name','sample_rate','channels','width','height','r_frame_rate']} for s in ss]},ensure_ascii=False))
